DeepSea.customGLSL:
/*
 * @node deepSea
 * @title Deep Sea
 * @category custom
 * @description Underwater backdrop for a camera ray rd: dark depths below, light shafts from the surface above.
 */
vec4 deepSea(vec3 rd, vec3 deep, vec3 shallow, float time) {
    float h = clamp(rd.y * 0.5 + 0.5, 0.0, 1.0);
    vec3 c = mix(deep, shallow, pow(h, 2.2));
    float rays = pow(max(sin(rd.x * 9.0 + time * 0.3) * sin(rd.z * 7.0 - time * 0.2), 0.0), 3.0) * smoothstep(0.45, 1.0, h);
    c += shallow * rays * 0.6;
    return vec4(c, 1.0);
}

Caustics.customGLSL:
/*
 * @node caustics
 * @title Caustics
 * @category custom
 * @description Cheap animated caustic pattern on a horizontal plane (0..1): sharp bright lines where waves focus the light.
 */
float caustics(vec3 p, float time) {
    vec2 q = p.xz * 1.3;
    float c = 0.0;
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        q += vec2(sin(q.y * 1.7 + time * 0.6 + fi), cos(q.x * 1.3 - time * 0.5 + fi * 2.0)) * 0.45;
        c += abs(sin(q.x + q.y) * cos(q.x * 0.7 - q.y * 1.1));
    }
    return pow(clamp(1.0 - c / 3.0, 0.0, 1.0), 4.0) * 2.5;
}

BrightPass.customGLSL:
/*
 * @node brightPass
 * @title Bright Pass
 * @category custom
 * @description The bright parts of a texture (luma above threshold), averaged over 4 taps: render it into a small Feedback for bloom.
 */
vec4 brightPass(sampler2D tex, float threshold) {
    vec2 uv = gl_FragCoord.xy / u_resolution;
    vec2 px = 1.0 / vec2(textureSize(tex, 0));
    vec3 c = texture(tex, uv + px * vec2(-1.0, -1.0)).rgb + texture(tex, uv + px * vec2(1.0, -1.0)).rgb
           + texture(tex, uv + px * vec2(-1.0, 1.0)).rgb + texture(tex, uv + px * vec2(1.0, 1.0)).rgb;
    c *= 0.25;
    float l = dot(c, vec3(0.2126, 0.7152, 0.0722));
    return vec4(c * smoothstep(threshold, threshold + 0.35, l), 1.0);
}

BloomGrade.customGLSL:
/*
 * @node bloomGrade
 * @title Bloom Grade
 * @category custom
 * @description Adds a soft 7x7 bloom of the bright pass to the scene, then a vignette and a gentle highlight roll-off.
 */
vec3 bloomGrade(sampler2D scene, sampler2D bloom, float amount, float vignette) {
    vec2 uv = gl_FragCoord.xy / u_resolution;
    vec3 c = texture(scene, uv).rgb;
    vec2 px = 1.0 / vec2(textureSize(bloom, 0));
    vec3 b = vec3(0.0);
    float ws = 0.0;
    for (int y = -3; y <= 3; y++) {
        for (int x = -3; x <= 3; x++) {
            float w = exp(-float(x * x + y * y) / 5.0);
            b += texture(bloom, uv + vec2(float(x), float(y)) * px).rgb * w;
            ws += w;
        }
    }
    c += b / ws * amount;
    float r = length((uv - 0.5) * vec2(1.0, 0.75));
    c *= mix(1.0, smoothstep(0.9, 0.2, r), vignette);
    return 1.0 - exp(-c * 1.4);
}
